        gLoadData.AccessModel(MODEL_ICE_GIANT_PART6, L"Data\\Monster\\", L"icegiantpart_6");
        gLoadData.OpenTexture(MODEL_ICE_GIANT_PART6, L"Monster\\");
    }
    break;
    }

    b->Actions[MONSTER01_STOP1].PlaySpeed = 0.25f;
